import numpy as np

# Generate first STS(15)
blocks1 = []
for a in range(1, 16):
    for b in range(a + 1, 16):
        c = a ^ b
        if c > b:
            blocks1.append((a, b, c))

# Find a permutation that makes the second STS(15) disjoint from the first
import random
random.seed(0)
while True:
    perm = list(range(1, 16))
    random.shuffle(perm)

    blocks2 = []
    for a, b, c in blocks1:
        new_block = tuple(sorted((perm[a-1], perm[b-1], perm[c-1])))
        blocks2.append(new_block)

    if len(set(blocks1).intersection(set(blocks2))) == 0:
        break

blocks_70 = blocks1 + blocks2

matrix = np.zeros((15, 70), dtype=int)
for j, block in enumerate(blocks_70):
    for p in block:
        matrix[p-1, j] = 1

# Verify constraints
assert np.all(matrix.sum(axis=1) == 14)
assert np.all(matrix.sum(axis=0) == 3)
for i1 in range(15):
    for i2 in range(i1 + 1, 15):
        assert np.dot(matrix[i1], matrix[i2]) == 2

print("Success")
print(matrix.flatten().tolist()[:20]) # print a few to check

import random

# Generate first STS(15)
blocks1 = []
for a in range(1, 16):
    for b in range(a + 1, 16):
        c = a ^ b
        if c > b:
            blocks1.append((a, b, c))

# Find a permutation that makes the second STS(15) disjoint from the first
random.seed(42)
while True:
    perm = list(range(1, 16))
    random.shuffle(perm)

    blocks2 = []
    for a, b, c in blocks1:
        new_block = tuple(sorted((perm[a-1], perm[b-1], perm[c-1])))
        blocks2.append(new_block)

    if len(set(blocks1).intersection(set(blocks2))) == 0:
        break

blocks_70 = blocks1 + blocks2

matrix = [[0]*70 for _ in range(15)]
for j, block in enumerate(blocks_70):
    for p in block:
        matrix[p-1][j] = 1

# Verify constraints
for row in matrix:
    assert sum(row) == 14

for j in range(70):
    assert sum(matrix[i][j] for i in range(15)) == 3

for i1 in range(15):
    for i2 in range(i1 + 1, 15):
        dot = sum(matrix[i1][j] * matrix[i2][j] for j in range(70))
        assert dot == 2

flat_matrix = [val for row in matrix for val in row]
print(flat_matrix)
